import { mapPluginConfigIssues } from "openclaw/plugin-sdk/extension-shared";
import {
  buildPluginConfigSchema,
  type OpenClawPluginConfigSchema,
} from "openclaw/plugin-sdk/plugin-entry";
import { asFiniteNumber, asOptionalRecord } from "openclaw/plugin-sdk/string-coerce-runtime";
import { clampInt, clampNumber } from "openclaw/plugin-sdk/text-utility-runtime";
import { z } from "zod";
import {
  DIFF_IMAGE_QUALITY_PRESETS,
  DIFF_INDICATORS,
  DIFF_LAYOUTS,
  DIFF_MODES,
  DIFF_OUTPUT_FORMATS,
  DIFF_THEMES,
  type DiffFileDefaults,
  type DiffImageQualityPreset,
  type DiffOutputFormat,
  type DiffToolDefaults,
} from "./types.js";
import { normalizeViewerBaseUrl } from "./url.js";

type DiffsPluginConfig = z.input<typeof DiffsPluginJsonSchemaSource>;

const DEFAULT_IMAGE_QUALITY_PROFILES = {
  standard: {
    scale: 2,
    maxWidth: 960,
    maxPixels: 8_000_000,
  },
  hq: {
    scale: 2.5,
    maxWidth: 1200,
    maxPixels: 14_000_000,
  },
  print: {
    scale: 3,
    maxWidth: 1400,
    maxPixels: 24_000_000,
  },
} as const satisfies Record<
  DiffImageQualityPreset,
  { scale: number; maxWidth: number; maxPixels: number }
>;

const DEFAULT_DIFFS_TOOL_DEFAULTS: DiffToolDefaults = {
  fontFamily: "Fira Code",
  fontSize: 15,
  lineSpacing: 1.6,
  layout: "unified",
  showLineNumbers: true,
  diffIndicators: "bars",
  wordWrap: true,
  background: true,
  theme: "dark",
  fileFormat: "png",
  fileQuality: "standard",
  fileScale: DEFAULT_IMAGE_QUALITY_PROFILES.standard.scale,
  fileMaxWidth: DEFAULT_IMAGE_QUALITY_PROFILES.standard.maxWidth,
  mode: "both",
  ttlSeconds: 1800,
};

const DEFAULT_DIFFS_PLUGIN_SECURITY = {
  allowRemoteViewer: false,
};

const VIEWER_BASE_URL_JSON_SCHEMA = {
  type: "string",
  format: "uri",
  pattern: "^[Hh][Tt][Tt][Pp][Ss]?://",
  not: {
    pattern: "[?#]",
  },
} as const satisfies Record<string, unknown>;

const DiffsPluginJsonSchemaSource = z.strictObject({
  viewerBaseUrl: z
    .string()
    .superRefine((value, ctx) => {
      try {
        normalizeViewerBaseUrl(value, "viewerBaseUrl");
      } catch (error) {
        ctx.addIssue({
          code: "custom",
          message: error instanceof Error ? error.message : "Invalid viewerBaseUrl",
        });
      }
    })
    .optional(),
  defaults: z
    .strictObject({
      fontFamily: z.string().default(DEFAULT_DIFFS_TOOL_DEFAULTS.fontFamily).optional(),
      fontSize: z.number().min(10).max(24).default(DEFAULT_DIFFS_TOOL_DEFAULTS.fontSize).optional(),
      lineSpacing: z
        .number()
        .min(1)
        .max(3)
        .default(DEFAULT_DIFFS_TOOL_DEFAULTS.lineSpacing)
        .optional(),
      layout: z.enum(DIFF_LAYOUTS).default(DEFAULT_DIFFS_TOOL_DEFAULTS.layout).optional(),
      showLineNumbers: z.boolean().default(DEFAULT_DIFFS_TOOL_DEFAULTS.showLineNumbers).optional(),
      diffIndicators: z
        .enum(DIFF_INDICATORS)
        .default(DEFAULT_DIFFS_TOOL_DEFAULTS.diffIndicators)
        .optional(),
      wordWrap: z.boolean().default(DEFAULT_DIFFS_TOOL_DEFAULTS.wordWrap).optional(),
      background: z.boolean().default(DEFAULT_DIFFS_TOOL_DEFAULTS.background).optional(),
      theme: z.enum(DIFF_THEMES).default(DEFAULT_DIFFS_TOOL_DEFAULTS.theme).optional(),
      fileFormat: z.enum(DIFF_OUTPUT_FORMATS).optional(),
      format: z.enum(DIFF_OUTPUT_FORMATS).optional().describe("Deprecated alias for fileFormat."),
      fileQuality: z.enum(DIFF_IMAGE_QUALITY_PRESETS).optional(),
      fileScale: z.number().min(1).max(4).optional(),
      fileMaxWidth: z.number().min(640).max(2400).optional(),
      imageFormat: z
        .enum(DIFF_OUTPUT_FORMATS)
        .optional()
        .describe("Deprecated alias for fileFormat."),
      imageQuality: z
        .enum(DIFF_IMAGE_QUALITY_PRESETS)
        .optional()
        .describe("Deprecated alias for fileQuality."),
      imageScale: z.number().min(1).max(4).optional().describe("Deprecated alias for fileScale."),
      imageMaxWidth: z
        .number()
        .min(640)
        .max(2400)
        .optional()
        .describe("Deprecated alias for fileMaxWidth."),
      mode: z.enum(DIFF_MODES).default(DEFAULT_DIFFS_TOOL_DEFAULTS.mode).optional(),
      ttlSeconds: z
        .number()
        .min(1)
        .max(21_600)
        .default(DEFAULT_DIFFS_TOOL_DEFAULTS.ttlSeconds)
        .optional(),
    })
    .optional(),
  security: z
    .strictObject({
      allowRemoteViewer: z
        .boolean()
        .default(DEFAULT_DIFFS_PLUGIN_SECURITY.allowRemoteViewer)
        .optional(),
    })
    .optional(),
});

const diffsPluginConfigSchemaBase = buildPluginConfigSchema(DiffsPluginJsonSchemaSource, {
  safeParse(value: unknown) {
    if (value === undefined) {
      return { success: true, data: undefined };
    }
    const result = DiffsPluginJsonSchemaSource.safeParse(value);
    if (result.success) {
      return {
        success: true,
        data: buildDiffsPluginConfigShape(result.data),
      };
    }
    return {
      success: false,
      error: {
        issues: mapPluginConfigIssues(result.error.issues),
      },
    };
  },
});

export const diffsPluginConfigSchema: OpenClawPluginConfigSchema = {
  ...diffsPluginConfigSchemaBase,
  jsonSchema: {
    ...diffsPluginConfigSchemaBase.jsonSchema,
    properties: {
      ...(diffsPluginConfigSchemaBase.jsonSchema as { properties?: Record<string, unknown> })
        .properties,
      viewerBaseUrl: VIEWER_BASE_URL_JSON_SCHEMA,
    },
  },
};

function buildDiffsPluginConfigShape(config: DiffsPluginConfig): DiffsPluginConfig {
  const viewerBaseUrl = resolveDiffsPluginViewerBaseUrl(config);
  return {
    ...(viewerBaseUrl !== undefined ? { viewerBaseUrl } : {}),
    ...(config.defaults !== undefined ? { defaults: resolveDiffsPluginDefaults(config) } : {}),
    ...(config.security !== undefined ? { security: resolveDiffsPluginSecurity(config) } : {}),
  };
}

export function resolveDiffsPluginDefaults(config: unknown): DiffToolDefaults {
  if (!config || typeof config !== "object" || Array.isArray(config)) {
    return { ...DEFAULT_DIFFS_TOOL_DEFAULTS };
  }

  const defaults = (config as DiffsPluginConfig).defaults;
  if (!defaults || typeof defaults !== "object" || Array.isArray(defaults)) {
    return { ...DEFAULT_DIFFS_TOOL_DEFAULTS };
  }

  const fileQuality = normalizeFileQuality(defaults.fileQuality ?? defaults.imageQuality);
  const profile = DEFAULT_IMAGE_QUALITY_PROFILES[fileQuality];
  const fileFormat =
    defaults.fileFormat ??
    (defaults.imageFormat !== undefined ? defaults.imageFormat : defaults.format);

  return {
    fontFamily: normalizeFontFamily(defaults.fontFamily),
    fontSize: normalizeDiffFontSize(defaults.fontSize),
    lineSpacing: normalizeDiffLineSpacing(defaults.lineSpacing),
    layout:
      DIFF_LAYOUTS.find((value) => value === defaults.layout) ?? DEFAULT_DIFFS_TOOL_DEFAULTS.layout,
    showLineNumbers: defaults.showLineNumbers !== false,
    diffIndicators:
      DIFF_INDICATORS.find((value) => value === defaults.diffIndicators) ??
      DEFAULT_DIFFS_TOOL_DEFAULTS.diffIndicators,
    wordWrap: defaults.wordWrap !== false,
    background: defaults.background !== false,
    theme:
      DIFF_THEMES.find((value) => value === defaults.theme) ?? DEFAULT_DIFFS_TOOL_DEFAULTS.theme,
    fileFormat: normalizeFileFormat(fileFormat),
    fileQuality,
    fileScale: normalizeFileScale(defaults.fileScale ?? defaults.imageScale, profile.scale),
    fileMaxWidth: normalizeFileMaxWidth(
      defaults.fileMaxWidth ?? defaults.imageMaxWidth,
      profile.maxWidth,
    ),
    mode: DIFF_MODES.find((value) => value === defaults.mode) ?? DEFAULT_DIFFS_TOOL_DEFAULTS.mode,
    ttlSeconds: normalizeTtlSeconds(defaults.ttlSeconds),
  };
}

export function resolveDiffsPluginSecurity(config: unknown) {
  return {
    allowRemoteViewer:
      asOptionalRecord(asOptionalRecord(config)?.security)?.allowRemoteViewer === true,
  };
}

export function resolveDiffsPluginViewerBaseUrl(config: unknown): string | undefined {
  const viewerBaseUrl = asOptionalRecord(config)?.viewerBaseUrl;
  if (typeof viewerBaseUrl !== "string") {
    return undefined;
  }

  const normalized = viewerBaseUrl.trim();
  return normalized ? normalizeViewerBaseUrl(normalized) : undefined;
}

function normalizeFontFamily(fontFamily?: string): string {
  const normalized = fontFamily?.trim();
  return normalized || DEFAULT_DIFFS_TOOL_DEFAULTS.fontFamily;
}

function normalizeDiffFontSize(fontSize?: number): number {
  return clampInt(asFiniteNumber(fontSize) ?? DEFAULT_DIFFS_TOOL_DEFAULTS.fontSize, 10, 24);
}

function normalizeDiffLineSpacing(lineSpacing?: number): number {
  return clampNumber(asFiniteNumber(lineSpacing) ?? DEFAULT_DIFFS_TOOL_DEFAULTS.lineSpacing, 1, 3);
}

function normalizeFileFormat(fileFormat?: DiffOutputFormat): DiffOutputFormat {
  return fileFormat && DIFF_OUTPUT_FORMATS.includes(fileFormat)
    ? fileFormat
    : DEFAULT_DIFFS_TOOL_DEFAULTS.fileFormat;
}

function normalizeFileQuality(fileQuality?: DiffImageQualityPreset): DiffImageQualityPreset {
  return fileQuality && DIFF_IMAGE_QUALITY_PRESETS.includes(fileQuality)
    ? fileQuality
    : DEFAULT_DIFFS_TOOL_DEFAULTS.fileQuality;
}

function normalizeFileScale(fileScale: number | undefined, fallback: number): number {
  const value = asFiniteNumber(fileScale);
  return value === undefined ? fallback : clampNumber(Math.round(value * 100) / 100, 1, 4);
}

function normalizeFileMaxWidth(fileMaxWidth: number | undefined, fallback: number): number {
  const value = asFiniteNumber(fileMaxWidth);
  return value === undefined ? fallback : clampNumber(Math.round(value), 640, 2400);
}

function normalizeTtlSeconds(ttlSeconds?: number): number {
  return clampInt(asFiniteNumber(ttlSeconds) ?? DEFAULT_DIFFS_TOOL_DEFAULTS.ttlSeconds, 1, 21_600);
}

export function resolveDiffImageRenderOptions(
  params: Partial<DiffFileDefaults> & { defaults: DiffFileDefaults },
) {
  const format = normalizeFileFormat(params.fileFormat ?? params.defaults.fileFormat);
  const qualityOverrideProvided = params.fileQuality !== undefined;
  const qualityPreset = normalizeFileQuality(params.fileQuality ?? params.defaults.fileQuality);
  const profile = DEFAULT_IMAGE_QUALITY_PROFILES[qualityPreset];

  const scale = normalizeFileScale(
    params.fileScale,
    qualityOverrideProvided ? profile.scale : params.defaults.fileScale,
  );
  const maxWidth = normalizeFileMaxWidth(
    params.fileMaxWidth,
    qualityOverrideProvided ? profile.maxWidth : params.defaults.fileMaxWidth,
  );

  return {
    format,
    qualityPreset,
    scale,
    maxWidth,
    maxPixels: profile.maxPixels,
  };
}

import type { FileContents, FileDiffMetadata } from "@pierre/diffs";
import { parsePatchFiles } from "@pierre/diffs";
import { preloadDiffHTML, type PreloadDiffOptions } from "@pierre/diffs/ssr";
import { escapeHtml } from "openclaw/plugin-sdk/text-utility-runtime";
import {
  collectDiffPayloadLanguageHints,
  isBaseDiffViewerLanguage,
  normalizeDiffViewerPayloadLanguages,
  normalizeSupportedLanguageHint,
} from "./language-hints.js";
import type {
  DiffInput,
  DiffRenderOptions,
  DiffRenderTarget,
  DiffViewerOptions,
  DiffViewerPayload,
  RenderedDiffDocument,
} from "./types.js";

const DEFAULT_FILE_NAME = "diff.txt";
const MAX_PATCH_FILE_COUNT = 128;
const MAX_PATCH_TOTAL_LINES = 120_000;
const VIEWER_LOADER_DOCUMENT_PATH = "../../assets/viewer.js";
const LANGUAGE_PACK_VIEWER_LOADER_DOCUMENT_PATH = "../../../diffs-language-pack/assets/viewer.js";

export class DiffInputError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ToolInputError";
  }
}

function escapeCssString(value: string): string {
  return value.replaceAll("\\", "\\\\").replaceAll('"', '\\"');
}

function escapeJsonScript(value: unknown): string {
  return JSON.stringify(value).replaceAll("<", "\\u003c");
}

function buildDiffTitle(input: DiffInput): string {
  if (input.title?.trim()) {
    return input.title.trim();
  }
  if (input.kind === "before_after") {
    return input.path?.trim() || "Text diff";
  }
  return "Patch diff";
}

function resolveDiffTypography(presentation: DiffRenderOptions["presentation"]) {
  const { fontSize, lineSpacing } = presentation;
  const lineHeight = Math.max(20, Math.round(fontSize * lineSpacing));
  return { fontSize, lineHeight };
}

function buildDiffOptions(options: DiffRenderOptions): DiffViewerOptions {
  const fontFamily = escapeCssString(options.presentation.fontFamily);
  const { fontSize, lineHeight } = resolveDiffTypography(options.presentation);
  return {
    theme: {
      light: "pierre-light",
      dark: "pierre-dark",
    },
    diffStyle: options.presentation.layout,
    diffIndicators: options.presentation.diffIndicators,
    disableLineNumbers: !options.presentation.showLineNumbers,
    expandUnchanged: options.expandUnchanged,
    themeType: options.presentation.theme,
    backgroundEnabled: options.presentation.background,
    overflow: options.presentation.wordWrap ? "wrap" : "scroll",
    unsafeCSS: `
      :host {
        --diffs-font-family: "${fontFamily}", "SF Mono", Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
        --diffs-header-font-family: "${fontFamily}", "SF Mono", Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
        --diffs-font-size: ${fontSize}px;
        --diffs-line-height: ${lineHeight}px;
      }

      [data-diffs-header] {
        min-height: 64px;
        padding-inline: 18px 14px;
      }

      [data-header-content] {
        gap: 10px;
      }

      [data-metadata] {
        gap: 10px;
      }

      .oc-diff-toolbar {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        margin-inline-start: 6px;
        flex: 0 0 auto;
      }

      .oc-diff-toolbar-button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 24px;
        height: 24px;
        padding: 0;
        margin: 0;
        border: 0;
        border-radius: 0;
        background: transparent;
        color: inherit;
        cursor: pointer;
        opacity: 0.6;
        line-height: 0;
        overflow: visible;
        transition: opacity 120ms ease;
        flex: 0 0 auto;
      }

      .oc-diff-toolbar-button:hover {
        opacity: 1;
      }

      .oc-diff-toolbar-button[data-active="true"] {
        opacity: 0.92;
      }

      .oc-diff-toolbar-button svg {
        display: block;
        width: 16px;
        height: 16px;
        min-width: 16px;
        min-height: 16px;
        overflow: visible;
        flex: 0 0 auto;
        color: inherit;
        fill: currentColor;
        pointer-events: none;
      }
    `,
  };
}

function buildImageRenderOptions(options: DiffRenderOptions): DiffRenderOptions {
  return {
    ...options,
    presentation: {
      ...options.presentation,
      fontSize: Math.max(16, options.presentation.fontSize),
    },
  };
}

function buildRenderVariants(options: DiffRenderOptions, target: DiffRenderTarget) {
  const viewerOptions =
    target === "viewer" || target === "both" ? buildDiffOptions(options) : undefined;
  const imageOptions =
    target === "image" || target === "both"
      ? buildDiffOptions(buildImageRenderOptions(options))
      : undefined;
  const preloadOptions = viewerOptions ?? imageOptions;
  if (!preloadOptions) {
    throw new Error(`Unsupported diff render target: ${target}`);
  }
  return { viewerOptions, imageOptions, preloadOptions };
}

function renderDiffCard(payload: DiffViewerPayload, anchorId?: string): string {
  return `<section class="oc-diff-card"${anchorId ? ` id="${anchorId}"` : ""}>
    <diffs-container class="oc-diff-host" data-openclaw-diff-host>
      <template shadowrootmode="open">${payload.prerenderedHTML}</template>
    </diffs-container>
    <script type="application/json" data-openclaw-diff-payload>${escapeJsonScript(payload)}</script>
  </section>`;
}

type FileDiffStats = ReturnType<typeof computeFileDiffStats>;

type FileNavEntry = {
  anchorId: string;
  fileDiff: FileDiffMetadata;
  stats: FileDiffStats;
};

// Hunk.additionLines/deletionLines count only +/- lines (not context), so the
// sums match the built-in per-file header counts rendered by @pierre/diffs.
function computeFileDiffStats(fileDiff: FileDiffMetadata) {
  let additions = 0;
  let deletions = 0;
  for (const hunk of fileDiff.hunks) {
    additions += hunk.additionLines;
    deletions += hunk.deletionLines;
  }
  return { additions, deletions };
}

function renderNavChangeBadge(changeType: FileDiffMetadata["type"]): string {
  const label =
    changeType === "new"
      ? "added"
      : changeType === "deleted"
        ? "deleted"
        : changeType === "rename-pure" || changeType === "rename-changed"
          ? "renamed"
          : undefined;
  return label ? `<span class="oc-diff-nav-badge" data-change="${label}">${label}</span>` : "";
}

function renderNavStats(stats: FileDiffStats): string {
  return `<span class="oc-diff-nav-stats"><span class="oc-diff-nav-additions">+${stats.additions}</span><span class="oc-diff-nav-deletions">-${stats.deletions}</span></span>`;
}

function renderNavEntryName(fileDiff: FileDiffMetadata): string {
  const renamed = fileDiff.prevName && fileDiff.prevName !== fileDiff.name;
  return renamed
    ? `${escapeHtml(fileDiff.prevName ?? "")} &rarr; ${escapeHtml(fileDiff.name)}`
    : escapeHtml(fileDiff.name);
}

// Multi-file patches render as stacked cards; this summary card gives per-file
// stats plus anchor links so long diffs stay navigable without extra JS.
function renderFileSummaryNav(entries: ReadonlyArray<FileNavEntry>): string {
  const totals = entries.reduce<FileDiffStats>(
    (sum, entry) => ({
      additions: sum.additions + entry.stats.additions,
      deletions: sum.deletions + entry.stats.deletions,
    }),
    { additions: 0, deletions: 0 },
  );
  const items = entries
    .map(
      (entry) =>
        `<li><a href="#${entry.anchorId}"><code>${renderNavEntryName(entry.fileDiff)}</code></a>${renderNavChangeBadge(entry.fileDiff.type)}${renderNavStats(entry.stats)}</li>`,
    )
    .join("\n      ");
  return `<nav class="oc-diff-card oc-diff-nav" aria-label="Changed files">
    <p class="oc-diff-nav-summary">${entries.length} changed files${renderNavStats(totals)}</p>
    <ol class="oc-diff-nav-list">
      ${items}
    </ol>
  </nav>`;
}

async function renderSection(
  input: { oldFile: FileContents; newFile: FileContents } | { fileDiff: FileDiffMetadata },
  { viewerOptions, imageOptions, preloadOptions }: ReturnType<typeof buildRenderVariants>,
  languagePackAvailable: boolean,
  anchorId?: string,
) {
  const prerenderedHTML = await preloadDiffHTMLWithFallback({ ...input, options: preloadOptions });
  const payload = await normalizeDiffViewerPayloadLanguages(
    {
      prerenderedHTML,
      ...input,
      options: preloadOptions,
      langs: collectDiffPayloadLanguageHints(input),
    },
    { languagePackAvailable },
  );
  return {
    ...(viewerOptions
      ? { viewer: renderDiffCard({ ...payload, options: viewerOptions }, anchorId) }
      : {}),
    ...(imageOptions
      ? { image: renderDiffCard({ ...payload, options: imageOptions }, anchorId) }
      : {}),
    usesLanguagePack: payload.langs.some((lang) => !isBaseDiffViewerLanguage(lang)),
  };
}

async function renderBeforeAfterDiff(
  input: Extract<DiffInput, { kind: "before_after" }>,
  options: DiffRenderOptions,
  target: DiffRenderTarget,
) {
  const languagePackAvailable = options.languagePackAvailable === true;
  const lang = await normalizeSupportedLanguageHint(input.lang, { languagePackAvailable });
  const fileName =
    input.path?.trim() ||
    (lang && lang !== "text" ? `diff.${lang.replace(/^\.+/, "")}` : DEFAULT_FILE_NAME);
  const oldFile: FileContents = {
    name: fileName,
    contents: input.before,
    ...(lang ? { lang } : {}),
  };
  const newFile: FileContents = {
    name: fileName,
    contents: input.after,
    ...(lang ? { lang } : {}),
  };
  const section = await renderSection(
    { oldFile, newFile },
    buildRenderVariants(options, target),
    languagePackAvailable,
  );

  return { sections: [section], leadingHtml: undefined };
}

async function renderPatchDiff(
  input: Extract<DiffInput, { kind: "patch" }>,
  options: DiffRenderOptions,
  target: DiffRenderTarget,
) {
  const languagePackAvailable = options.languagePackAvailable === true;
  const files = parsePatchFiles(input.patch).flatMap((entry) => entry.files ?? []);
  if (files.length === 0) {
    throw new DiffInputError("Patch input did not contain any file diffs.");
  }
  if (files.length > MAX_PATCH_FILE_COUNT) {
    throw new DiffInputError(`Patch input contains too many files (max ${MAX_PATCH_FILE_COUNT}).`);
  }
  const totalLines = files.reduce((sum, fileDiff) => {
    const splitLines = Number.isFinite(fileDiff.splitLineCount) ? fileDiff.splitLineCount : 0;
    const unifiedLines = Number.isFinite(fileDiff.unifiedLineCount) ? fileDiff.unifiedLineCount : 0;
    return sum + Math.max(splitLines, unifiedLines, 0);
  }, 0);
  if (totalLines > MAX_PATCH_TOTAL_LINES) {
    throw new DiffInputError(
      `Patch input is too large to render (max ${MAX_PATCH_TOTAL_LINES} lines).`,
    );
  }

  const variants = buildRenderVariants(options, target);
  const navEntries: FileNavEntry[] = files.map((fileDiff, index) => ({
    anchorId: `oc-diff-file-${index + 1}`,
    fileDiff,
    stats: computeFileDiffStats(fileDiff),
  }));
  const sections = await Promise.all(
    files.map((fileDiff, index) =>
      renderSection({ fileDiff }, variants, languagePackAvailable, navEntries[index]?.anchorId),
    ),
  );
  // Single-file patches skip the summary card; one file needs no navigation.
  const navHtml = files.length > 1 ? renderFileSummaryNav(navEntries) : undefined;

  return { sections, leadingHtml: navHtml };
}

export async function renderDiffDocument(
  input: DiffInput,
  options: DiffRenderOptions,
  target: DiffRenderTarget = "both",
): Promise<RenderedDiffDocument> {
  const title = buildDiffTitle(input);
  const { sections, leadingHtml } =
    input.kind === "before_after"
      ? await renderBeforeAfterDiff(input, options, target)
      : await renderPatchDiff(input, options, target);
  const lead = leadingHtml ? [leadingHtml] : [];
  const viewerSections = sections.flatMap((section) => (section.viewer ? [section.viewer] : []));
  const imageSections = sections.flatMap((section) => (section.image ? [section.image] : []));
  const viewerBodyHtml = viewerSections.length
    ? [...lead, ...viewerSections].join("\n")
    : undefined;
  const imageBodyHtml = imageSections.length ? [...lead, ...imageSections].join("\n") : undefined;
  const viewerRuntime = sections.some((section) => section.usesLanguagePack)
    ? "language-pack"
    : "base";
  const imageTypography = resolveDiffTypography(buildImageRenderOptions(options).presentation);
  const document = (bodyHtml: string, runtimeMode: "viewer" | "image") => {
    const theme = options.presentation.theme;
    const imageMaxWidth = options.image.maxWidth;
    const viewerLoaderPath =
      viewerRuntime === "language-pack"
        ? LANGUAGE_PACK_VIEWER_LOADER_DOCUMENT_PATH
        : VIEWER_LOADER_DOCUMENT_PATH;
    const imageTypographyCss =
      runtimeMode === "image"
        ? `
      .oc-frame[data-render-mode="image"] .oc-diff-host {
        --diffs-font-size: ${imageTypography.fontSize}px;
        --diffs-line-height: ${imageTypography.lineHeight}px;
      }
`
        : "";
    return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <meta name="color-scheme" content="dark light" />
    <title>${escapeHtml(title)}</title>
    <style>
      * {
        box-sizing: border-box;
      }

      html,
      body {
        min-height: 100%;
      }

      html {
        background: #05070b;
        scroll-behavior: smooth;
      }

      @media (prefers-reduced-motion: reduce) {
        html {
          scroll-behavior: auto;
        }
      }

      body {
        margin: 0;
        min-height: 100vh;
        padding: 22px;
        font-family:
          "Fira Code",
          "SF Mono",
          Monaco,
          Consolas,
          monospace;
        background: #05070b;
        color: #f8fafc;
      }

      body[data-theme="light"] {
        background: #f3f5f8;
        color: #0f172a;
      }

      .oc-frame {
        max-width: 1560px;
