export type DiffFileDefaults = {
  fileFormat: DiffOutputFormat;
  fileQuality: DiffImageQualityPreset;
  fileScale: number;
  fileMaxWidth: number;
};

export type DiffToolDefaults = DiffPresentationDefaults &
  DiffFileDefaults & {
    mode: DiffMode;
    ttlSeconds: number;
  };

type BeforeAfterDiffInput = {
  kind: "before_after";
