export type DiffViewerPayload = {
  prerenderedHTML: string;
  options: DiffViewerOptions;
  langs: SupportedLanguages[];
  oldFile?: FileContents;
  newFile?: FileContents;
  fileDiff?: FileDiffMetadata;
};

export type RenderedDiffDocument = {
  html?: string;
  imageHtml?: string;
  title: string;
