export const DIFF_LAYOUTS = ["unified", "split"] as const;
export const DIFF_MODES = ["view", "image", "file", "both"] as const;
export const DIFF_THEMES = ["light", "dark"] as const;
export const DIFF_INDICATORS = ["bars", "classic", "none"] as const;
export const DIFF_IMAGE_QUALITY_PRESETS = ["standard", "hq", "print"] as const;
export const DIFF_OUTPUT_FORMATS = ["png", "pdf"] as const;

export function clampNumber(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

/** Floors a number before clamping it to an inclusive min/max range. */
export function clampInt(value: number, min: number, max: number): number {
  return clampNumber(Math.floor(value), min, max);
}

export class DiffInputError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ToolInputError";
  }
}

export function readNumberParam(
  params: Record<string, unknown>,
  key: string,
  options: {
    required?: boolean;
    label?: string;
    integer?: boolean;
    strict?: boolean;
    positiveInteger?: boolean;
    nonNegativeInteger?: boolean;
  } = {},
): number | undefined {
  const {
    required = false,
    label = key,
    integer = false,
    strict = false,
    positiveInteger = false,
    nonNegativeInteger = false,
  } = options;
  const raw = readSnakeCaseParamRaw(params, key);
  let value: number | undefined;
  if (typeof raw === "number" && Number.isFinite(raw)) {
    value = raw;
  } else if (typeof raw === "string") {
    const trimmed = raw.trim();
    if (trimmed) {
      const parsed = strict ? parseStrictFiniteNumber(trimmed) : Number.parseFloat(trimmed);
      if (parsed !== undefined && Number.isFinite(parsed)) {
        value = parsed;
      }
    }
  }
  if (value === undefined) {
    if (required) {
      throw new ToolInputError(`${label} required`);
    }
    return undefined;
  }
  if (positiveInteger) {
    return asPositiveSafeInteger(value);
  }
  if (nonNegativeInteger) {
    return asSafeIntegerInRange(value, { min: 0 });
  }
  return integer ? Math.trunc(value) : value;
}

// Blank optional numbers are absent; nonblank invalid input keeps the caller's error.
function readStrictNumberParam(
  params: Record<string, unknown>,
  key: string,
  message: string,
  nonNegativeInteger = false,
): number | undefined {
  const value = readNumberParam(params, key, { strict: true, nonNegativeInteger });
  if (value === undefined) {
    const raw = readSnakeCaseParamRaw(params, key);
    if (raw != null && !(typeof raw === "string" && raw.trim() === "")) {
      throw new ToolInputError(message);
    }
  }
  return value;
}

export function readPositiveIntegerParam(
  params: Record<string, unknown>,
  key: string,
  options: {
    message?: string;
    max?: number;
  } = {},
): number | undefined {
  const message = options.message ?? `${key} must be a positive integer`;
  const value = readNonNegativeIntegerParam(params, key, { ...options, message });
  if (value === 0) {
    throw new ToolInputError(message);
  }
  return value;
}

export function readNonNegativeIntegerParam(
  params: Record<string, unknown>,
  key: string,
  options: {
    message?: string;
    max?: number;
  } = {},
): number | undefined {
  const message = options.message ?? `${key} must be a non-negative integer`;
  const value = readStrictNumberParam(params, key, message, true);
  if (value !== undefined && options.max !== undefined && value > options.max) {
    throw new ToolInputError(message);
  }
  return value;
}

export function readFiniteNumberParam(
  params: Record<string, unknown>,
  key: string,
  options: {
    message?: string;
    min?: number;
    max?: number;
    minExclusive?: boolean;
    maxExclusive?: boolean;
  } = {},
): number | undefined {
  const message = options.message ?? `${key} must be a finite number`;
  const value = readStrictNumberParam(params, key, message);
  if (value === undefined) {
    return undefined;
  }
  if (
    (options.min !== undefined &&
      (options.minExclusive ? value <= options.min : value < options.min)) ||
    (options.max !== undefined &&
      (options.maxExclusive ? value >= options.max : value > options.max))
  ) {
    throw new ToolInputError(message);
  }
  return value;
}

const DEFAULT_IMAGE_QUALITY_PROFILES = {
  standard: {
    scale: 2,
    maxWidth: 960,
    maxPixels: 8_000_000,
  },
  hq: {
    scale: 2.5,
    maxWidth: 1200,
    maxPixels: 14_000_000,
  },
  print: {
    scale: 3,
    maxWidth: 1400,
    maxPixels: 24_000_000,
  },
} as const satisfies Record<
  DiffImageQualityPreset,
  { scale: number; maxWidth: number; maxPixels: number }
>;

const DEFAULT_DIFFS_TOOL_DEFAULTS: DiffToolDefaults = {
  fontFamily: "Fira Code",
  fontSize: 15,
  lineSpacing: 1.6,
  layout: "unified",
  showLineNumbers: true,
  diffIndicators: "bars",
  wordWrap: true,
  background: true,
  theme: "dark",
  fileFormat: "png",
  fileQuality: "standard",
  fileScale: DEFAULT_IMAGE_QUALITY_PROFILES.standard.scale,
  fileMaxWidth: DEFAULT_IMAGE_QUALITY_PROFILES.standard.maxWidth,
  mode: "both",
  ttlSeconds: 1800,
};

function normalizeFileFormat(fileFormat?: DiffOutputFormat): DiffOutputFormat {
  return fileFormat && DIFF_OUTPUT_FORMATS.includes(fileFormat)
    ? fileFormat
    : DEFAULT_DIFFS_TOOL_DEFAULTS.fileFormat;
}

function normalizeFileQuality(fileQuality?: DiffImageQualityPreset): DiffImageQualityPreset {
  return fileQuality && DIFF_IMAGE_QUALITY_PRESETS.includes(fileQuality)
    ? fileQuality
    : DEFAULT_DIFFS_TOOL_DEFAULTS.fileQuality;
}

function normalizeFileScale(fileScale: number | undefined, fallback: number): number {
  const value = asFiniteNumber(fileScale);
  return value === undefined ? fallback : clampNumber(Math.round(value * 100) / 100, 1, 4);
}

function normalizeFileMaxWidth(fileMaxWidth: number | undefined, fallback: number): number {
  const value = asFiniteNumber(fileMaxWidth);
  return value === undefined ? fallback : clampNumber(Math.round(value), 640, 2400);
}

export function resolveDiffImageRenderOptions(
  params: Partial<DiffFileDefaults> & { defaults: DiffFileDefaults },
) {
  const format = normalizeFileFormat(params.fileFormat ?? params.defaults.fileFormat);
  const qualityOverrideProvided = params.fileQuality !== undefined;
  const qualityPreset = normalizeFileQuality(params.fileQuality ?? params.defaults.fileQuality);
  const profile = DEFAULT_IMAGE_QUALITY_PROFILES[qualityPreset];

  const scale = normalizeFileScale(
    params.fileScale,
    qualityOverrideProvided ? profile.scale : params.defaults.fileScale,
  );
  const maxWidth = normalizeFileMaxWidth(
    params.fileMaxWidth,
    qualityOverrideProvided ? profile.maxWidth : params.defaults.fileMaxWidth,
  );

  return {
    format,
    qualityPreset,
    scale,
    maxWidth,
    maxPixels: profile.maxPixels,
  };
}

const MAX_BEFORE_AFTER_BYTES = 512 * 1024;
const MAX_PATCH_BYTES = 2 * 1024 * 1024;
const MAX_TITLE_BYTES = 1_024;
const MAX_PATH_BYTES = 2_048;
const MAX_LANG_BYTES = 128;
const MAX_DIFF_ARTIFACT_TTL_SECONDS = 21_600;

function buildArtifactContext(
  context: OpenClawPluginToolContext | undefined,
): DiffArtifactContext | undefined {
  if (!context) {
    return undefined;
  }

  const artifactContext: DiffArtifactContext = {};
  for (const key of ["agentId", "sessionId", "messageChannel", "agentAccountId"] as const) {
    const value = normalizeOptionalString(context[key]);
    if (value) {
      artifactContext[key] = value;
    }
  }

  return Object.keys(artifactContext).length > 0 ? artifactContext : undefined;
}

function normalizeDiffInput(params: DiffsToolParams): DiffInput {
  const patch = params.patch?.trim();
  const before = params.before;
  const after = params.after;

  if (patch) {
    assertMaxBytes(patch, "patch", MAX_PATCH_BYTES);
    if (before !== undefined || after !== undefined) {
      throw new DiffInputError("Provide either patch or before/after input, not both.");
    }
    const title = params.title?.trim();
    if (title) {
      assertMaxBytes(title, "title", MAX_TITLE_BYTES);
    }
    return {
      kind: "patch",
      patch,
      title,
    };
  }

  if (before === undefined || after === undefined) {
    throw new DiffInputError("Provide patch or both before and after text.");
  }
  assertMaxBytes(before, "before", MAX_BEFORE_AFTER_BYTES);
  assertMaxBytes(after, "after", MAX_BEFORE_AFTER_BYTES);
  const path = normalizeOptionalString(params.path);
  const lang = normalizeOptionalString(params.lang);
  const title = normalizeOptionalString(params.title);
  if (path) {
    assertMaxBytes(path, "path", MAX_PATH_BYTES);
  }
  if (lang) {
    assertMaxBytes(lang, "lang", MAX_LANG_BYTES);
  }
  if (title) {
    assertMaxBytes(title, "title", MAX_TITLE_BYTES);
  }

  return {
    kind: "before_after",
    before,
    after,
    path,
    lang,
    title,
  };
}

function assertMaxBytes(value: string, label: string, maxBytes: number): void {
  if (Buffer.byteLength(value, "utf8") <= maxBytes) {
    return;
  }
  throw new DiffInputError(`${label} exceeds maximum size (${maxBytes} bytes).`);
}

function normalizeTtlMs(ttlSeconds: number): number {
  return Math.floor(Math.min(Math.max(ttlSeconds, 1), MAX_DIFF_ARTIFACT_TTL_SECONDS) * 1000);
}

const artifactContext = buildArtifactContext(params.context);
const input = normalizeDiffInput(toolParams);
if (input.kind === "before_after" && input.before === input.after) {
  return textResult("Before and after are identical — no changes to render.", {
    changed: false,
    ...(artifactContext ? { context: artifactContext } : {}),
  });
}
const mode = DIFF_MODES.find((value) => value === toolParams.mode) ?? params.defaults.mode;
const theme =
  DIFF_THEMES.find((value) => value === toolParams.theme) ?? params.defaults.theme;
const layout =
  DIFF_LAYOUTS.find((value) => value === toolParams.layout) ?? params.defaults.layout;
const expandUnchanged = toolParams.expandUnchanged === true;
const ttlSeconds =
  readFiniteNumberParam(rawRecord, "ttlSeconds") ?? params.defaults.ttlSeconds;
const fileScale = readFiniteNumberParam(rawRecord, "fileScale");
const fileMaxWidth = readFiniteNumberParam(rawRecord, "fileMaxWidth");
const ttlMs = normalizeTtlMs(ttlSeconds);
const image = resolveDiffImageRenderOptions({
  defaults: params.defaults,
  fileFormat: DIFF_OUTPUT_FORMATS.find((value) => value === toolParams.fileFormat),
  fileQuality: DIFF_IMAGE_QUALITY_PRESETS.find((value) => value === toolParams.fileQuality),
  fileScale,
  fileMaxWidth,
});
const artifactOnly = mode === "image" || mode === "file";
const renderTarget = mode === "view" ? "viewer" : artifactOnly ? "image" : "both";

{
  presentation: {
    ...params.defaults,
    layout,
    theme,
  },
  image,
  expandUnchanged,
  languagePackAvailable: params.languagePackAvailable,
}

